local activeTween = nil

-- Glide the root part to the destination with TweenService instead of an
-- instant CFrame set. The gradual move avoids anticheat teleport detection,
-- and unanchoring afterward lets you walk normally without being pulled back.
local function teleportTo(cframe)
    local player = Players.LocalPlayer
    local char = player and player.Character
    if not char then
        return
    end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not hrp then
        return
    end
    lastTeleportCF = cframe

    if activeTween then
        activeTween:Cancel()
        activeTween = nil
    end

    if hrp.Anchored then
        hrp.Anchored = false
    end

    if teleportMode == "cframe" then
        hrp.CFrame = cframe
        return
    end

    -- Tha Bronx anticheat bypass: drop into the FallingDown state, wait for the
    -- anticheat's LastACPos attribute to clear, then apply the CFrame and get up.
    if teleportMode == "bypass" then
        local humanoid = char:FindFirstChild("Humanoid")
        if not humanoid then
            hrp.CFrame = cframe
            return
        end
        humanoid:ChangeState(Enum.HumanoidStateType.FallingDown)
        local num = 1
        repeat
            task.wait()
            num = num + 1
        until num >= 40 and not player:GetAttribute("LastACPos")
        hrp.CFrame = cframe
        task.wait()
        humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
        return
    end

    local dist = (hrp.Position - cframe.Position).Magnitude
    local duration = math.clamp(dist / TWEEN_SPEED, 0.15, 10)

    hrp.AssemblyLinearVelocity = Vector3.zero
    hrp.Anchored = true
    local tween = TweenService:Create(
        hrp,
        TweenInfo.new(duration, Enum.EasingStyle.Linear),
        { CFrame = cframe }
    )
    activeTween = tween
    tween.Completed:Connect(function()
        if hrp and hrp.Parent then
            hrp.Anchored = false
        end
        if activeTween == tween then
            activeTween = nil
        end
    end)
    tween:Play()
end

-- While the bypass is on, hard-lock the player to the last teleport position
-- every frame so the game can't drag us back.
RunService.Heartbeat:Connect(function()
    if not antiTeleport or not lastTeleportCF then
        return
    end
    local player = Players.LocalPlayer
    local char = player and player.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if hrp then
        hrp.CFrame = lastTeleportCF
        hrp.AssemblyLinearVelocity = Vector3.zero
    end
end)

antiTpBtn.MouseButton1Click:Connect(function()
    antiTeleport = not antiTeleport
    if antiTeleport then
        antiTpBtn.Text = "Anti-TP Bypass: ON"
        antiTpBtn.BackgroundColor3 = Color3.fromRGB(46, 120, 70)
        -- Lock to current position if we haven't teleported yet.
        if not lastTeleportCF then
            local player = Players.LocalPlayer
            local char = player and player.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if hrp then
                lastTeleportCF = hrp.CFrame
            end
        end
    else
        antiTpBtn.Text = "Anti-TP Bypass: OFF"
        antiTpBtn.BackgroundColor3 = Color3.fromRGB(60, 60, 70)
    end
end)

