-- Dragging (mouse + touch) via the title bar.
local dragging = false
local dragStart, startPos

titleBar.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
        dragging = true
        dragStart = input.Position
        startPos = main.Position
        input.Changed:Connect(function()
            if input.UserInputState == Enum.UserInputState.End then
                dragging = false
            end
        end)
    end
end)

UserInputService.InputChanged:Connect(function(input)
    if dragging
        and (input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch) then
        local delta = input.Position - dragStart
        main.Position = UDim2.new(
            startPos.X.Scale, startPos.X.Offset + delta.X,
            startPos.Y.Scale, startPos.Y.Offset + delta.Y
        )
    end
end)

-- Toggle + execution loop.
local enabled = false
local loopToken = 0
local selectedItem = nil -- name of the Tool chosen in the dropdown
local autoDrop = false -- forward-declared so the dupe loop can drop before running

local function updateStatus()
    local itemText = selectedItem and ("Item: " .. selectedItem) or "Item: none"
    local stateText = enabled
        and ("Status: ON (every " .. RUN_INTERVAL .. "s)")
        or "Status: OFF"
    status.Text = stateText .. "\n" .. itemText
end

local function setVisualState(on)
    if on then
        toggle.Text = "Stop Dupe"
        toggle.BackgroundColor3 = Color3.fromRGB(196, 64, 64)
    else
        toggle.Text = "Start Dupe"
        toggle.BackgroundColor3 = Color3.fromRGB(60, 60, 70)
    end
    updateStatus()
end

-- Inventory helpers.
local function getInventoryTools()
    local tools = {}
    local player = Players.LocalPlayer
    if not player then
        return tools
    end
    local backpack = player:FindFirstChildOfClass("Backpack")
    if backpack then
        for _, t in ipairs(backpack:GetChildren()) do
            if t:IsA("Tool") then
                table.insert(tools, t)
            end
        end
    end
    local char = player.Character
    if char then
        for _, t in ipairs(char:GetChildren()) do
            if t:IsA("Tool") then
                table.insert(tools, t)
            end
        end
    end
    return tools
end

local function findTool(name)
    for _, t in ipairs(getInventoryTools()) do
        if t.Name == name then
            return t
        end
    end
    return nil
end

local function toolsNamed(name)
    local matches = {}
    for _, t in ipairs(getInventoryTools()) do
        if t.Name == name then
            table.insert(matches, t)
        end
    end
    return matches
end

-- Press the in-game drop key (G) to drop the currently held tool.
local function pressDropKey()
    local vim = game:GetService("VirtualInputManager")
    pcall(function()
        vim:SendKeyEvent(true, Enum.KeyCode.G, false, game)
        task.wait(0.05)
        vim:SendKeyEvent(false, Enum.KeyCode.G, false, game)
    end)
end

-- When 2+ copies of `name` are held, equip one and drop it with the G keybind.
local function dropExtra(name)
    local matches = toolsNamed(name)
    if #matches < 2 then
        return
    end
    local player = Players.LocalPlayer
    local char = player and player.Character
    local humanoid = char and char:FindFirstChildOfClass("Humanoid")
    local tool = matches[#matches]
    if humanoid and tool then
        pcall(function()
            humanoid:EquipTool(tool)
        end)
        task.wait(0.1)
    end
    pressDropKey()
end

-- Equip the selected tool (if in the backpack) so payloads that dupe the
-- currently held tool act on the chosen item. Returns the Tool (or nil).
local function equipSelected()
    local player = Players.LocalPlayer
    if not player or not selectedItem then
        return nil
    end
    local char = player.Character
    local tool = findTool(selectedItem)
    if tool and char then
        local humanoid = char:FindFirstChildOfClass("Humanoid")
        if humanoid and tool.Parent ~= char then
            pcall(function()
                humanoid:EquipTool(tool)
            end)
        end
    end
    return tool
end

-- Dropdown open/close + population.
local function closeList()
    listFrame.Visible = false
    selector.Text = (selectedItem and ("Item: " .. selectedItem) or "Select item")
        .. " ▼"
end

local function refreshList()
    for _, c in ipairs(listFrame:GetChildren()) do
        if c:IsA("TextButton") then
            c:Destroy()
        end
    end
    local seen = {}
    local count = 0
    for _, t in ipairs(getInventoryTools()) do
        if not seen[t.Name] then
            seen[t.Name] = true
            count = count + 1
            local btn = Instance.new("TextButton")
            btn.Size = UDim2.new(1, -4, 0, 26)
            btn.BackgroundColor3 = Color3.fromRGB(56, 56, 66)
            btn.BorderSizePixel = 0
            btn.Font = Enum.Font.Gotham
            btn.TextSize = 13
            btn.TextColor3 = Color3.fromRGB(230, 230, 235)
            btn.Text = t.Name
            btn.ZIndex = 11
            btn.LayoutOrder = count
            btn.Parent = listFrame
            local name = t.Name
            btn.MouseButton1Click:Connect(function()
                selectedItem = name
                closeList()
                updateStatus()
            end)
        end
    end
    if count == 0 then
        local empty = Instance.new("TextButton")
        empty.Name = "Empty"
        empty.Size = UDim2.new(1, -4, 0, 26)
        empty.BackgroundTransparency = 1
        empty.AutoButtonColor = false
        empty.Font = Enum.Font.Gotham
        empty.TextSize = 13
        empty.TextColor3 = Color3.fromRGB(160, 160, 170)
        empty.Text = "(no tools found)"
        empty.ZIndex = 11
        empty.Parent = listFrame
        count = 1
    end
    listFrame.CanvasSize = UDim2.new(0, 0, 0, count * 28)
end

selector.MouseButton1Click:Connect(function()
    if listFrame.Visible then
        closeList()
    else
        refreshList()
        listFrame.Visible = true
    end
end)

local function safeRun()
    local tool = equipSelected()
    local ok, err = pcall(runDupe, tool)
    if not ok then
        warn("[DUPE] execution error: " .. tostring(err))
        status.Text = "Status: ON (last run errored)\n"
            .. (selectedItem and ("Item: " .. selectedItem) or "Item: none")
    end
end

local function startLoop()
    loopToken = loopToken + 1
    local myToken = loopToken
    task.spawn(function()
        while enabled and myToken == loopToken do
            -- Drop a spare copy of the selected item before each dupe.
            if autoDrop and selectedItem then
                dropExtra(selectedItem)
            end
            safeRun()
            -- Interruptible wait so toggling OFF stops promptly.
            local waited = 0
            while enabled and myToken == loopToken and waited < RUN_INTERVAL do
                task.wait(1)
                waited = waited + 1
            end
        end
    end)
end

local function setDupe(on)
    on = on == true
    if on == enabled then
        setVisualState(enabled)
        return
    end
    enabled = on
    setVisualState(enabled)
    if enabled then
        startLoop()
    else
        loopToken = loopToken + 1 -- invalidate any running loop
    end
end

toggle.MouseButton1Click:Connect(function()
    setDupe(not enabled)
end)

regFlag("dupe", function()
    return enabled
end, function(v)
    setDupe(v)
end)

-- ==== Max Money: valary's "Generate Max Illegal Money" (IceFruit dupe) ====
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local StarterGui = game:GetService("StarterGui")

local function fireProx(prompt)
    if prompt and typeof(fireproximityprompt) == "function" then
        pcall(fireproximityprompt, prompt)
    end
end

local function getFruitCup()
    local player = Players.LocalPlayer
    for _, container in ipairs({ player:FindFirstChildOfClass("Backpack"), player.Character }) do
        if container then
            for _, v in ipairs(container:GetChildren()) do
                if v:IsA("Tool") and v.Name == "Ice-Fruit Cupz" then
                    local transparency
                    pcall(function()
                        transparency = v["IceFruit Cup"]["IceFruit PunchMedium"].Transparency
                    end)
                    if transparency ~= nil and transparency ~= 1 then
                        return true, v
                    end
                end
            end
        end
    end
    return false, nil
end

-- One-shot: generate the max amount of illegal cash via the IceFruit sell
-- exploit. Ported from valary's "Generate Max Illegal Money" button, with the
-- valary.gg black-screen overlay (HideScreen/SetText) stripped out.
local function generateMaxMoney()
    local player = Players.LocalPlayer
    local char = player and player.Character
    if not char then
        return
    end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    local hum = char:FindFirstChild("Humanoid")
    if not hrp or not hum then
        return
    end
    local backpack = player:FindFirstChildOfClass("Backpack")

    -- Fast path: already holding a finished cup, just spam-sell it.
    local found, cup = getFruitCup()
    if cup and found then
        local oldCF = hrp.CFrame
        if backpack and cup.Parent == backpack then
            hum:EquipTool(cup)
            task.wait(1)
        end
        teleportTo(workspace["IceFruit Sell"].CFrame)
        task.wait(0.5)
        for _ = 1, 4000 do
            task.spawn(function()
                fireProx(workspace["IceFruit Sell"].ProximityPrompt)
            end)
        end
        teleportTo(oldCF)
        return
    end

    local oldCF = hrp.CFrame
    local itemz = { "FijiWater", "FreshWater", "Ice-Fruit Bag", "Ice-Fruit Cupz" }

    local stove
    for _, v in ipairs(workspace.CookingPots:GetChildren()) do
        if v:IsA("Model") then
            local prompt = v:FindFirstChildWhichIsA("ProximityPrompt", true)
            if prompt and prompt.ActionText == "Turn On" and prompt.Enabled then
                stove = v
                break
            end
        end
    end

    for _, name in ipairs(itemz) do
        if not (backpack and backpack:FindFirstChild(name)) then
            pcall(function()
                ReplicatedStorage:WaitForChild("ExoticShopRemote"):InvokeServer(name)
            end)
            task.wait(1)
        end
    end

    for _, name in ipairs(itemz) do
        if not (backpack and backpack:FindFirstChild(name)) then
            -- Couldn't buy the products (need ~$5,000). Bail quietly.
            return
        end
    end

    if not stove then
        return
    end

    teleportTo(stove.CookPart.CFrame)
    task.wait(1)

    pcall(function()
        StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Backpack, false)
    end)
    hrp.Anchored = true

    task.wait(1.5)
    fireProx(stove:FindFirstChildWhichIsA("ProximityPrompt", true))
    task.wait(2)

    for _, name in ipairs({ "FijiWater", "FreshWater", "Ice-Fruit Bag" }) do
        local tool = backpack and backpack:FindFirstChild(name)
        if tool then
            hum:EquipTool(tool)
        end
        task.wait(1)
        fireProx(stove:FindFirstChildWhichIsA("ProximityPrompt", true))
        task.wait(3)
    end

    repeat
        task.wait()
    until stove.CookPart.Steam.LoadUI.Enabled == false

    if not char:FindFirstChild("Ice-Fruit Cupz") then
        local tool = backpack and backpack:FindFirstChild("Ice-Fruit Cupz")
        if tool then
            hum:EquipTool(tool)
        end
        task.wait(1)
    end

    task.wait(1)
    fireProx(stove:FindFirstChildWhichIsA("ProximityPrompt", true))
    task.wait(3)

    hrp.Anchored = false
    teleportTo(workspace["IceFruit Sell"].CFrame)
    task.wait(1)
    hrp.Anchored = true
    task.wait(1.5)

    if not char:FindFirstChild("Ice-Fruit Cupz") then
        local tool = backpack and backpack:FindFirstChild("Ice-Fruit Cupz")
        if tool then
            hum:EquipTool(tool)
        end
        task.wait(1)
    end

    workspace["IceFruit Sell"].ProximityPrompt.HoldDuration = 0
    for _ = 1, 4000 do
        task.spawn(function()
            fireProx(workspace["IceFruit Sell"].ProximityPrompt)
        end)
    end

    hrp.Anchored = false
    pcall(function()
        StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Backpack, true)
    end)
    task.wait(0.5)
    teleportTo(oldCF)
end

